#include <stdint.h>
#include "my_stm_helper.h"
#include "config.h"

// 3 states used by roll, pitch and tilt fsms
typedef enum { 
    STATE_FREE, STATE_COMPLIANT, STATE_CLAMPED 
} State_t;

// 2 operating modes
typedef enum {
    MODE_MANUAL, 
    MODE_AUTOPILOT
} Mode_t;

volatile bool tick_flag = false; // set every 20ms by TIM17

// TIM17 only raises a flag
void TIM17_IRQHandler(void) {
    if (TIM17->SR & (1<<0)) {
        TIM17->SR &= ~(1<<0);
        tick_flag = true; // tell main loop that a new cycle is due
    }
}

// simple fsm for all 3 states used for roll, pitch and tilt
// mag=|angle| in deg, *state is updated in place
void State_Update(State_t *state, float mag, float comp_in, float clamp_in, float comp_out, float free_out) {
    switch (*state) {
        case STATE_FREE:
            if (mag >= clamp_in) {
                *state = STATE_CLAMPED; // jumped straight past compliant
            } else if (mag >= comp_in) {
                *state = STATE_COMPLIANT;
            }
            break;

        case STATE_COMPLIANT:
            if (mag >= clamp_in) {
                *state = STATE_CLAMPED;
            }
            else if (mag < free_out) {
                *state = STATE_FREE;
            }
            break;

        case STATE_CLAMPED:
            if (mag < comp_out) {
                *state = STATE_COMPLIANT; // must fall below exit thresh to leave
            }
            break;
    }
}

// servo angle (deg) for roll or pitch from its state
// servo=90-angle because clockwise = increasing servo angle (from fig 1 breif)
float Axis_Servo_Angle(State_t state, float angle) {
    switch (state) {
        case STATE_FREE:
            return 90.0f; // centred

        case STATE_COMPLIANT: 
            return 90.0f - angle; // follows the stick

        default: 
            // clamped at 90 -/+ 50
            if (angle >= 0) {
                return 40.0f;
            } else {
                return 140.0f;
            }
    }
}

// servo angle (deg) for tilt from its state, tilt is always >= 0
float Tilt_Servo_Angle(State_t state, float tilt) {
    switch (state) {
        case STATE_FREE:
            return 0.0f;
        case STATE_COMPLIANT: 
            return 2.0f * tilt;// x2 tilt
        default:
            return 140.0f; // clamped
    }
}

// mode fsm: manual, autopilot
// button_pressed is true for ONE cycle only (rising edge of the button)
void Mode_Update(Mode_t *mode, bool btn_pressed, State_t roll_state, State_t pitch_state) {
    switch (*mode) {
        case MODE_MANUAL:
            // button pressed or both roll and pitch clamped, hand over to autopilot
            if (btn_pressed || (roll_state == STATE_CLAMPED && pitch_state == STATE_CLAMPED)) {
                *mode = MODE_AUTOPILOT;
            }
            break;

        case MODE_AUTOPILOT:
            // pilot can only take back control if button pressed AND roll and pitch both free
            if (btn_pressed && roll_state == STATE_FREE && pitch_state == STATE_FREE) {
                *mode = MODE_MANUAL;
            }
            break;
    }
}

int main(void) {
    Master_Init(); // clocks, pins, timers, pwm, i2c, wake mpu

    float ax, ay, az, roll, pitch, tilt;
    float abs_roll, abs_pitch; // abs values for the state fsms

    // all three fsms start in the free state
    State_t roll_state = STATE_FREE;
    State_t pitch_state= STATE_FREE;
    State_t tilt_state = STATE_FREE;

    // mode fsm starts in manual, btn edge detection
    Mode_t mode = MODE_MANUAL;
    bool btn_now;
    bool btn_prev = false;
    bool btn_pressed;

    while (1) {
        while (!tick_flag); // wait for the 20 ms tick
        tick_flag = false;

        if (!Read_Accel(&ax, &ay, &az)) {
            I2C1->CR1 &= ~(1<<0);// read failed: reset i2c
            I2C1->CR1 |=  (1<<0);
            continue; // skip this cycle
        }
        Calc_Angles(ax, ay, az, &roll, &pitch, &tilt);

        // abs value of roll and pitch 
        abs_roll = roll;
        if (abs_roll < 0.0f) {
            abs_roll = -abs_roll;
        }
        abs_pitch = pitch;
        if (abs_pitch < 0.0f) {
            abs_pitch = -abs_pitch;
        }

        // update the roll, pitch and tilt state fsms
        State_Update(&roll_state, abs_roll, AXIS_COMPLIANT_IN, AXIS_CLAMPED_IN, AXIS_COMPLIANT_OUT, AXIS_FREE_OUT);
        State_Update(&pitch_state, abs_pitch, AXIS_COMPLIANT_IN, AXIS_CLAMPED_IN, AXIS_COMPLIANT_OUT, AXIS_FREE_OUT);
        State_Update(&tilt_state, tilt, TILT_COMPLIANT_IN, TILT_CLAMPED_IN, TILT_COMPLIANT_OUT, TILT_FREE_OUT);

        // btn rising edge: pressed now but not on prev cycle (20ms sample also debounces)
        btn_now = GPIO_InputReadPin(GPIOA, AUTO_BUTTON);
        btn_pressed = btn_now && !btn_prev;
        btn_prev = btn_now;

        // update mode fsm using this cycle's roll and pitch states
        Mode_Update(&mode, btn_pressed, roll_state, pitch_state);

        // leds show the current mode
        if (mode == MODE_AUTOPILOT) {
            GPIO_OutputSetPin(GPIOA, LED_AUTO);
            GPIO_OutputClearPin(GPIOB, LED_MANUAL);
        } else {
            GPIO_OutputClearPin(GPIOA, LED_AUTO);
            GPIO_OutputSetPin(GPIOB, LED_MANUAL);
        }

        // drive the servos from the fsm outputs
        TIM3_PWM_SetPulse(SERVO_ROLL,  Angle_To_Pulse(Axis_Servo_Angle(roll_state,  roll)));
        TIM3_PWM_SetPulse(SERVO_PITCH, Angle_To_Pulse(Axis_Servo_Angle(pitch_state, pitch)));
        TIM3_PWM_SetPulse(SERVO_TILT,  Angle_To_Pulse(Tilt_Servo_Angle(tilt_state,  tilt)));
    }
}
